"""The generated files of an app (Epic 22), next to the overlay's app kit. No LLM.

src/content/app.json             the outline's navigation and every page's app sections (the kit renders them)
src/components/app/bindings.ts   operationId → fetcher / query keys / mutation (`codegen.bindings_ts`)
src/components/app/icons.ts      the Lucide icons the navigation names, imported one by one
src/components/app/form-schemas.ts  form id → its generated Zod schema and defaults (`src/lib/forms.ts`)
src/app/<route>/page.tsx         metadata + <AppPage pageId=… />
"""

import json
from typing import Any

from src.modules.shared.domain.backend_spec.naming import pluralize, to_kebab, to_pascal
from src.modules.shared.domain.frontend_spec.icons import lucide_current, lucide_files
from src.orchestrator.integration.contract import contract_operations, resolve

from ...checks.consistency import _response_record
from ..codegen import bindings_ts
from ..renderer import form_schemas_ts

HEADER = "// Generated by the Fullstack Generation Agent from the FrontendSpec. Do not edit.\n"
APP_FILE = "src/content/app.json"
BINDINGS_FILE = "src/components/app/bindings.ts"
ICONS_FILE = "src/components/app/icons.ts"
FORM_SCHEMAS_FILE = "src/components/app/form-schemas.ts"
SCENARIOS_FILE = "src/mocks/scenarios.json"
# The error codes the mock API answers as the backend does (Story 22.4); scenarios expecting another code (a rule, a
# conflict, sign-in) are listed as not emulated, never as passed.
EMULATED_CODES = frozenset({"NOT_FOUND", "REFERENCE_NOT_FOUND"})
DEFAULT_ICON = "LayoutGrid"


def icon_name(name: str | None, default: str = DEFAULT_ICON) -> str:
    """A Lucide component name the base has (renamed icons by their current name), else the default."""
    files = lucide_files()
    if name and name in files:
        return name
    current = lucide_current(name) if name else None
    return current if current in files else default


def _field_type(schema: dict[str, Any]) -> dict[str, Any]:
    """How the kit shows a response field: `string`, `text`, `integer`, `number`, `boolean`, `date`, `datetime`,
    `enum` (with `values`), `reference` (a parent's `{id, label}`), `list` or `object`."""
    for option in schema.get("anyOf") or []:
        if option.get("type") != "null":
            schema = {**schema, **option}
    kind = schema.get("type")
    kind = next((t for t in kind if t != "null"), None) if isinstance(kind, list) else kind
    values = [value for value in schema.get("enum") or [] if value is not None]
    if values:
        return {"type": "enum", "values": values}
    if schema.get("format") == "date":
        return {"type": "date"}
    if schema.get("format") == "date-time":
        return {"type": "datetime"}
    if kind in ("integer", "number", "boolean"):
        return {"type": kind}
    if kind == "array":
        return {"type": "list"}
    if kind == "object" or "properties" in schema:
        return {"type": "object"}
    return {"type": "text" if (schema.get("maxLength") or 0) > 255 else "string"}


def app_entities(spec: dict[str, Any], contract: dict[str, Any] | None, pages: dict[str, str]) -> dict[str, Any]:
    """Per entity: how the outline names and shows it, the type of each field its records have, and its parents
    (a foreign key → the `{id, label}` summary the record carries and the parent's page)."""
    outline = (spec.get("app") or {}).get("entities") or {}
    if contract is None:
        return {}
    info = (contract.get("x-bga") or {}).get("entities") or {}
    operations = contract_operations(contract)
    out: dict[str, Any] = {}
    for name, shown in outline.items():
        found = next(
            (
                found
                for action in ("get", "list")
                for found in operations.values()
                if (found["operation"].get("x-bga") or {}).get("entity") == name
                and (found["operation"].get("x-bga") or {}).get("action") == action
                and not (found["operation"].get("x-bga") or {}).get("mock")
            ),
            None,
        )
        record = _response_record(contract, found["operation"]) if found else {}
        fields = {
            field: _field_type(resolve(contract, schema)) for field, schema in (record.get("properties") or {}).items()
        }
        slug = to_kebab(pluralize(name))
        references = {}
        for reference in (info.get(name) or {}).get("references") or []:
            parent_page = f"{to_kebab(pluralize(reference['entity']))}-id"
            references[reference["field"]] = {
                "summary": reference["apiName"],
                "entity": reference["entity"],
                "href": pages.get(parent_page),
            }
            fields[reference["field"]] = {"type": "reference"}
            fields[reference["apiName"]] = {"type": "summary"}
        list_op = next(
            (
                op_id
                for op_id, found in operations.items()
                if (found["operation"].get("x-bga") or {}).get("entity") == name
                and (found["operation"].get("x-bga") or {}).get("action") == "list"
                and not (found["operation"].get("x-bga") or {}).get("mock")
            ),
            None,
        )
        out[name] = {
            **shown,
            "listOperation": list_op,
            "fields": fields,
            "references": references,
            "detail": pages.get(f"{slug}-id"),
            "list": pages.get(slug),
        }
    return out


def app_data(plan: dict[str, Any], spec: dict[str, Any], contract: dict[str, Any] | None = None) -> dict[str, Any]:
    outline = spec.get("app") or {}
    pages = {route["pageId"]: route["route"] for route in plan["routes"]}
    nav = []
    for item in (plan.get("app") or {}).get("nav") or []:
        if item.get("page") in pages:
            nav.append({"label": item["label"], "href": pages[item["page"]], "icon": icon_name(item.get("icon"))})
    return {
        "name": outline.get("name") or spec["project"]["name"],
        "tagline": outline.get("tagline"),
        "icon": icon_name(outline.get("icon"), "Boxes"),
        "home": pages.get("home", "/"),
        "nav": nav,
        "pages": {
            route["pageId"]: {"title": route["title"], "route": route["route"], "sections": route["sections"]}
            for route in plan["routes"]
        },
        "density": (spec.get("theme") or {}).get("density") or "comfortable",
        "routes": pages,
        "errors": app_errors(contract),
        "entities": app_entities(spec, contract, pages),
        "forms": {form["id"]: _form(form) for form in spec.get("forms") or []},
    }


def app_errors(contract: dict[str, Any] | None) -> dict[str, list[dict[str, Any]]]:
    """operationId → its errors (`x-bga.errors`): the kit shows their message, on their `fields` when they name any."""
    out: dict[str, list[dict[str, Any]]] = {}
    for op_id, found in contract_operations(contract).items() if contract else []:
        errors = (found["operation"].get("x-bga") or {}).get("errors") or []
        if errors:
            out[op_id] = [
                {key: error[key] for key in ("status", "code", "message", "fields") if error.get(key) is not None}
                for error in errors
            ]
    return out


def mock_scenarios(contract: dict[str, Any] | None) -> dict[str, Any]:
    """The contract's scenarios the mocks emulate (`src/mocks/scenarios.test.ts` runs them) and the others by
    reason. Plugin operations and signed-in scenarios wait for Story 22.7."""
    emulated: list[dict[str, Any]] = []
    skipped: dict[str, int] = {}
    for op_id, found in sorted(contract_operations(contract).items()) if contract else []:
        meta = found["operation"].get("x-bga") or {}
        for scenario in meta.get("scenarios") or []:
            expect = scenario.get("expect") or {}
            code = expect.get("code")
            if meta.get("plugin") or found["operation"].get("security") or scenario.get("user"):
                reason = "sign-in (22.7)"
            elif expect.get("status", 500) < 300 or code in EMULATED_CODES:
                reason = None
            elif code == "VALIDATION_ERROR" and scenario.get("name", "").startswith("missing"):
                reason = None
            else:
                reason = code or str(expect.get("status"))
            if reason:
                skipped[reason] = skipped.get(reason, 0) + 1
                continue
            emulated.append(
                {
                    "operationId": op_id,
                    "method": found["method"],
                    "path": found["path"],
                    "name": scenario.get("name", ""),
                    **({"params": scenario["params"]} if scenario.get("params") else {}),
                    **({"body": scenario["body"]} if "body" in scenario else {}),
                    "expect": {key: expect[key] for key in ("status", "code") if expect.get(key) is not None},
                }
            )
    return {"scenarios": emulated, "notEmulated": dict(sorted(skipped.items()))}


def _form(form: dict[str, Any]) -> dict[str, Any]:
    keys = ("operationId", "params", "load", "fields", "submitLabel", "onSuccess")
    return {key: form[key] for key in keys if form.get(key) is not None}


def icons_ts(data: dict[str, Any]) -> str:
    names = sorted({data["icon"], *(item["icon"] for item in data["nav"])})
    files = lucide_files()
    imports = "".join(f'import Lucide{name} from "lucide-react/icons/{files[name]}";\n' for name in names)
    entries = "".join(f"  {name}: Lucide{name},\n" for name in names)
    return (
        HEADER
        + 'import type { LucideIcon } from "lucide-react";\n'
        + imports
        + "\n/** The icons the app's navigation names, by Lucide name. */\n"
        + f"export const icons: Record<string, LucideIcon> = {{\n{entries}}};\n"
    )


def route_page(route: dict[str, Any]) -> str:
    seo = route.get("seo") or {}
    metadata = {"title": seo.get("title") or route["title"]}
    if seo.get("description"):
        metadata["description"] = seo["description"]
    return (
        HEADER
        + 'import type { Metadata } from "next";\n'
        + 'import { AppPage } from "@/components/app/AppPage";\n\n'
        + f"export const metadata: Metadata = {json.dumps(metadata, ensure_ascii=False)};\n\n"
        + f"export default function {to_pascal(route['pageId'].replace('-', '_'))}Page() {{\n"
        + f"  return <AppPage pageId={json.dumps(route['pageId'])} />;\n"
        + "}\n"
    )


def app_files(plan: dict[str, Any], spec: dict[str, Any], contract: dict[str, Any] | None) -> dict[str, str]:
    data = app_data(plan, spec, contract)
    files = {
        APP_FILE: json.dumps(data, indent=2, ensure_ascii=False) + "\n",
        BINDINGS_FILE: bindings_ts(contract),
        ICONS_FILE: icons_ts(data),
        FORM_SCHEMAS_FILE: form_schemas_ts(plan),
        SCENARIOS_FILE: json.dumps(mock_scenarios(contract), indent=2, ensure_ascii=False) + "\n",
    }
    for route in plan["routes"]:
        files[route["file"]] = route_page(route)
    return files
